import { createMathRandom, createNanoIdGenerator, createTime, loggerFactory, } from "@evolu/common";
import { createDbWorker } from "@evolu/common/evolu";
import { wrapWebWorkerSelf } from "../WebWorker.js";
import { sqliteFactory } from "./SqliteFactory.js";
const dbWorker = createDbWorker({
    ...createMathRandom(),
    ...createTime(),
    ...loggerFactory,
    ...createNanoIdGenerator(),
    ...sqliteFactory,
});
wrapWebWorkerSelf(dbWorker);
