/**
 * 🎲
 *
 * @module
 */
import { Random } from "random";
/** Creates {@link MathRandom} using Math.random(). */
export const createMathRandom = () => ({
    next: () => Math.random(),
});
/**
 * Creates {@link MathRandom} using {@link NpmRandom} with a seed which is useful
 * for tests.
 */
export const createMathRandomWithSeed = (seed) => {
    const random = new Random(seed);
    return {
        next: () => random.next(),
    };
};
/** Creates {@link NpmRandom} using the NPM `random` package. */
export const createNpmRandom = () => {
    return {
        random: new Random(),
    };
};
/**
 * Creates {@link NpmRandom} using the NPM `random` package with a seed which is
 * useful for tests.
 */
export const createNpmRandomWithSeed = (seed) => ({
    random: new Random(seed),
});
export const randomizeArray = (deps) => (array) => {
    if (array.length === 0) {
        return [];
    }
    const randomized = [...array];
    for (let index = array.length - 1; index > 0; index--) {
        const newIndex = Math.floor(deps.next() * (index + 1));
        [randomized[index], randomized[newIndex]] = [
            randomized[newIndex],
            randomized[index],
        ];
    }
    return randomized;
};
