/**
 * ⏳
 *
 * @module
 */
/** Creates a {@link Time} service using Date.now(). */
export const createTime = () => ({
    now: () => Date.now(),
});
/**
 * Creates a {@link Time} service that returns a monotonically increasing number
 * based on a queueMicrotask.
 */
export const createTestTime = () => {
    let now = 0;
    return {
        now: () => {
            const current = now;
            queueMicrotask(() => {
                now++;
            });
            return current;
        },
    };
};
