import { constVoid, createNanoIdGenerator, errorToTransferableError, exhaustiveCheck, } from "@evolu/common";
import { createNamespaceName, isSqlMutation, maybeLogQueryExecutionTime, } from "@evolu/common/evolu";
import sqlite3InitModule from "@sqlite.org/sqlite-wasm";
// https://github.com/sqlite/sqlite-wasm/issues/62
// @ts-expect-error Missing types.
globalThis.sqlite3ApiConfig = {
    warn: constVoid,
};
// Init ASAP.
const sqlite3Promise = sqlite3InitModule();
/**
 * "opfs-sahpool" does not support multiple simultaneous connections, and it can
 * be instantiated only within a web worker and only within one tab of the same
 * origin. We use Web Locks and BroadcastChannel to enable multiple tabs
 * functionality.
 *
 * - https://sqlite.org/wasm/doc/trunk/persistence.md
 *
 * There is a sophisticated workaround by the great rhashimoto:
 * https://github.com/rhashimoto/wa-sqlite/discussions/81
 *
 * We decided not to use it because we can't use SharedWorker in Chrome Android,
 * and I don't want to use ServiceWorker because it's slower and tricky.
 *
 * This implementation doesn't need SharedWorker or ServiceWorker and does not
 * use dedicated broadcast channels to keep code as simple as possible. Browsers
 * are updating OPFS rapidly, so we may not need this workaround at all in the
 * future.
 */
export const sqliteFactory = {
    createSqlite: (deps) => {
        const { nanoid } = createNanoIdGenerator();
        const channel = createSqliteBroadcastChannel(deps);
        const callbacks = new Map();
        const maybeCallCallback = (message) => {
            const callback = callbacks.get(message.id);
            if (callback) {
                callbacks.delete(message.id);
                callback(message);
            }
        };
        /**
         * We don't know which tab will be elected leader, and messages are
         * dispatched before initialization, so we must store them.
         */
        let execsBeforeSqliteInit = [];
        /** Handle incoming messages for a tab without initialized Sqlite. */
        channel.onMessage = (message) => {
            switch (message.type) {
                case "Exec": {
                    execsBeforeSqliteInit = [...execsBeforeSqliteInit, message];
                    break;
                }
                case "ExecError":
                case "ExecSuccess": {
                    /** Remove already handled exec so the other tabs will not process it. */
                    execsBeforeSqliteInit = execsBeforeSqliteInit.filter((m) => m.id !== message.id);
                    maybeCallCallback(message);
                    break;
                }
                default:
                    exhaustiveCheck(message);
            }
        };
        const { promise: init, resolve: resolveInit } = Promise.withResolvers();
        const connectionLockName = createNamespaceName(deps)("SqliteConnection");
        void navigator.locks.request(connectionLockName, () => 
        /**
         * This promise prevents other tabs from acquiring the lock because it's
         * never resolved or rejected. The next SQLite instance is created when
         * the previous lock is released (a tab is reloaded or closed).
         */
        new Promise(() => {
            resolveInit(true);
        }));
        void init.then(async () => {
            const sqlite3 = await sqlite3Promise;
            const poolUtil = await sqlite3.installOpfsSAHPoolVfs({ name: deps.name });
            const sqlite = new poolUtil.OpfsSAHPoolDb("/evolu1.db");
            const preparedStmts = new Map();
            const exec = (query, id) => {
                maybeLogQueryExecutionTime(query)(() => {
                    if (query.sql === exportDatabaseQuery.sql) {
                        const file = sqlite3.capi.sqlite3_js_db_export(sqlite);
                        return Promise.resolve([{ file }]);
                    }
                    if (query.options?.prepare) {
                        let prepared = preparedStmts.get(query.sql);
                        if (!prepared) {
                            prepared = sqlite.prepare(query.sql);
                            preparedStmts.set(query.sql, prepared);
                        }
                        prepared.bind(query.parameters ?? []);
                        if (isSqlMutation(query.sql)) {
                            prepared.stepReset();
                            return Promise.resolve([]);
                        }
                        const rows = [];
                        while (prepared.step()) {
                            rows.push(prepared.get({}));
                        }
                        prepared.reset();
                        return Promise.resolve(rows);
                    }
                    return Promise.resolve(sqlite.exec(query.sql, {
                        returnValue: "resultRows",
                        rowMode: "object",
                        bind: query.parameters ?? [],
                    }));
                }).then((rows) => {
                    channel.postMessage({
                        type: "ExecSuccess",
                        id,
                        result: { rows, changes: sqlite.changes() },
                    });
                }, (error) => {
                    channel.postMessage({
                        type: "ExecError",
                        id,
                        error: errorToTransferableError(error),
                    });
                });
            };
            /** A tab was elected so it can start processing. */
            channel.onMessage = (message) => {
                switch (message.type) {
                    case "Exec":
                        exec(message.query, message.id);
                        break;
                    case "ExecSuccess":
                    case "ExecError":
                        maybeCallCallback(message);
                        break;
                    default:
                        exhaustiveCheck(message);
                }
            };
            /** Handle execs arrived before Sqlite was initialized. */
            execsBeforeSqliteInit.forEach((message) => {
                exec(message.query, message.id);
            });
            execsBeforeSqliteInit = [];
        });
        const transactionLockName = createNamespaceName(deps)("SqliteTransaction");
        const sqlite = {
            exec: (query) => {
                const id = nanoid();
                return new Promise((resolve, reject) => {
                    callbacks.set(id, (message) => {
                        switch (message.type) {
                            case "ExecSuccess":
                                resolve(message.result);
                                break;
                            case "ExecError":
                                // It's TransferableError.
                                // eslint-disable-next-line @typescript-eslint/prefer-promise-reject-errors
                                reject(message.error);
                                break;
                        }
                    });
                    channel.postMessage({ type: "Exec", id, query });
                });
            },
            transaction: (mode) => async (callback) => {
                await navigator.locks.request(transactionLockName, 
                // Shared mode isn't possible for Web (yet).
                { mode: mode === "last" ? "exclusive" : mode }, async () => {
                    await callback();
                    if (mode === "last") {
                        // Don't resolve the last transaction; otherwise, it won't be the last.
                        await new Promise(constVoid);
                    }
                });
            },
            export: () => {
                const id = nanoid();
                return new Promise((resolve, reject) => {
                    callbacks.set(id, (message) => {
                        switch (message.type) {
                            case "ExecSuccess":
                                resolve(message.result.rows[0].file);
                                break;
                            case "ExecError":
                                // It's TransferableError.
                                // eslint-disable-next-line @typescript-eslint/prefer-promise-reject-errors
                                reject(message.error);
                                break;
                        }
                    });
                    channel.postMessage({
                        type: "Exec",
                        id,
                        query: exportDatabaseQuery,
                    });
                });
            },
        };
        return sqlite;
    },
};
const createSqliteBroadcastChannel = (config) => {
    const channelName = createNamespaceName(config)("SqliteBroadcastChannel");
    const channel = new BroadcastChannel(channelName);
    const sqliteChannel = {
        postMessage: (message) => {
            channel.postMessage(message);
            // Send to itself as well.
            sqliteChannel.onMessage(message);
        },
        onMessage: constVoid,
    };
    channel.onmessage = (e) => {
        sqliteChannel.onMessage(e.data);
    };
    return sqliteChannel;
};
// There is no such query; we are just enriching API.
const exportDatabaseQuery = {
    sql: `export database`,
    parameters: [],
};
