import { xsalsa20poly1305 } from "@noble/ciphers/salsa";
import { hmac } from "@noble/hashes/hmac";
import { sha256 } from "@noble/hashes/sha256";
import { sha512 } from "@noble/hashes/sha512";
import { concatBytes, randomBytes } from "@noble/hashes/utils";
import * as bip39 from "@scure/bip39";
import { getOrThrow } from "../Result.js";
import { NonNegativeInt } from "../Type.js";
import { createTimestamp } from "./Timestamp.js";
export const deriveOwnerIdAndEncryptionKey = (deps) => (mnemonic) => {
    const seed = mnemonicToMnemonicSeed(mnemonic);
    const ownerIdKey = slip21Derive(seed, ["Evolu", "Owner Id"]);
    let ownerId = "";
    /** Convert the key to the {@link Id} Base64Url format. */
    for (let i = 0; i < 21; i++) {
        ownerId = (ownerId + deps.urlAlphabet[ownerIdKey[i] & 63]);
    }
    const encryptionKey = slip21Derive(seed, [
        "Evolu",
        "Encryption Key",
    ]);
    return { ownerId, encryptionKey };
};
const mnemonicToMnemonicSeed = (mnemonic) => bip39.mnemonicToSeedSync(mnemonic);
/**
 * SLIP-21 implementation
 * https://github.com/satoshilabs/slips/blob/master/slip-0021.md
 */
const slip21Derive = (seed, path) => {
    let m = hmac(sha512, "Symmetric key seed", seed);
    for (const component of path) {
        const p = new TextEncoder().encode(component);
        const e = new Uint8Array(p.byteLength + 1);
        e[0] = 0;
        e.set(p, 1);
        m = hmac(sha512, m.slice(0, 32), e);
    }
    return m.slice(32, 64);
};
export const createInitialTimestamp = (deps) => {
    const hexAlphabet = "0123456789abcdef";
    const nodeId = deps.customAlphabet(hexAlphabet, 16)();
    return createTimestamp({ nodeId });
};
export const createRandomBytes = () => ({
    randomBytes: (bytesLength = 32) => randomBytes(bytesLength),
});
// Note this is not the whole nonce used for xsalsa20poly1305.
const nonceLength = getOrThrow(NonNegativeInt.from(8));
export const createSymmetricCrypto = (deps) => ({
    nonceLength,
    encrypt: (plaintext, encryptionKey, timestamp) => {
        const nonce = deps.randomBytes(nonceLength);
        /**
         * Using ${@link BinaryTimestamp} for the nonce is safe because
         * ${@link Timestamp} is globally unique counter. Check ${@link NodeId} docs.
         *
         * Xsalsa20poly1305 needs 24 bytes nonce, so we add random 8 bytes as extra
         * hardening. With this approach, we saved 16 bytes for each encrypted
         * change.
         */
        const fullNonce = concatBytes(timestamp, nonce);
        const ciphertext = xsalsa20poly1305(encryptionKey, fullNonce).encrypt(plaintext);
        return { nonce, ciphertext };
    },
    decrypt: (ciphertext, encryptionKey, timestamp, nonce) => {
        const fullNonce = concatBytes(timestamp, nonce);
        return xsalsa20poly1305(encryptionKey, fullNonce).decrypt(ciphertext);
    },
});
export const fingerprintSize = getOrThrow(NonNegativeInt.from(12));
/**
 * Converts an {@link BinaryTimestamp} into a {@link Fingerprint} by applying a
 * SHA-256 hash to the timestamp and truncating it to the first 12 bytes.
 */
export const binaryTimestampToFingerprint = (timestamp) => {
    const hash = sha256(timestamp).slice(0, fingerprintSize);
    return hash;
};
