export const prepare = (sqlQuery) => ({
    ...sqlQuery,
    options: { ...sqlQuery.options, prepare: true },
});
const isIdentifier = (value) => typeof value === "object" && value != null && "__type" in value;
export const identifier = (name) => ({
    __type: "Identifier",
    name,
});
const ID_WRAP_REGEX = /"/g;
/** From Kysely */
export const sanitizeIdentifier = (identifier) => identifier.name.replace(ID_WRAP_REGEX, '""');
/** Tagged literal function to create {@link SqliteQuery}. */
export const sql = (strings, ...parameters) => {
    let query = "";
    const params = [];
    for (let i = 0; i < strings.length; i++) {
        query += strings[i];
        if (i < parameters.length) {
            const param = parameters[i];
            if (isIdentifier(param)) {
                query += `"` + sanitizeIdentifier(param) + `"`;
            }
            else {
                query += "?";
                params.push(param);
            }
        }
    }
    return { sql: query, parameters: params };
};
/** This is good enough detection because SQL strings in Evolu are predictable. */
const isSqlMutationRegEx = new RegExp(`\\b(${[
    "alter",
    "create",
    "delete",
    "drop",
    "insert",
    "replace",
    "update",
].join("|")})\\b`);
export const isSqlMutation = (sql) => isSqlMutationRegEx.test(sql);
/**
 * Adds common features to the SQLite instance.
 *
 * - Logging.
 * - Transactions.
 */
export const addCommonSqliteFeatures = (deps) => ({
    exec: async (query) => {
        deps.log("[sql]", query);
        const result = await deps.exec(query);
        deps.log("[sql]", result);
        return result;
    },
    /**
     * Executes a transactional operation in SQLite with the specified mode. This
     * is a platform-agnostic implementation that ensures consistent behavior
     * across all supported platforms.
     */
    transaction: (mode) => async (callback) => {
        await deps.transaction(mode)(async () => {
            if (mode === "shared") {
                await callback();
                return;
            }
            try {
                deps.log("[sql] begin");
                await deps.exec(sql `begin;`);
                await callback();
                deps.log("[sql] commit");
                await deps.exec(sql `commit;`);
            }
            catch (error) {
                deps.log("[sql] rollback");
                await deps.exec(sql `rollback;`);
                throw error;
            }
        });
    },
    export: deps.export,
});
export const maybeLogQueryExecutionTime = (query) => async (callback) => {
    if (!query.options?.logQueryExecutionTime) {
        return callback();
    }
    const start = performance.now();
    const result = await callback();
    const elapsed = performance.now() - start;
    // eslint-disable-next-line no-console
    console.log(`QueryExecutionTime: ${elapsed.toString()}ms`, query);
    return result;
};
export const explainQueryPlan = (deps) => async (query) => {
    const { rows } = await deps.exec({
        ...query,
        sql: `EXPLAIN QUERY PLAN ${query.sql}`,
    });
    // eslint-disable-next-line no-console
    console.log("ExplainQueryPlan", query);
    // eslint-disable-next-line no-console
    console.log(drawSqliteQueryPlan(rows));
};
const drawSqliteQueryPlan = (rows) => rows
    .map((row) => {
    let parentId = row.parent;
    let indent = 0;
    do {
        const parent = rows.find((r) => r.id === parentId);
        if (!parent)
            break;
        parentId = parent.parent;
        indent++;
        // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition, no-constant-condition
    } while (true);
    return `${"  ".repeat(indent)}${row.detail}`;
})
    .join("\n");
/**
 * Enforce sequential execution of transactions for single-thread environments
 * like React Native or Node.js.
 */
export const createSingleThreadTransactionLock = () => {
    let promiseChain = Promise.resolve();
    const transaction = () => (callback) => {
        promiseChain = promiseChain.then(callback);
        return promiseChain;
    };
    return transaction;
};
