import { protocolVersion } from "./Protocol.js";
import { identifier, prepare, sanitizeIdentifier, sql, } from "./Sqlite.js";
/** Converts a 12-byte fingerprint into two Int64String values. */
export const fingerprintToFingerprintInts = (fingerprint) => {
    let part1 = BigInt(0);
    let part2 = BigInt(0);
    for (let i = 0; i < 6; i++) {
        part1 = (part1 << BigInt(8)) | BigInt(fingerprint[i]);
    }
    for (let i = 6; i < 12; i++) {
        part2 = (part2 << BigInt(8)) | BigInt(fingerprint[i]);
    }
    return [part1.toString(), part2.toString()];
};
/** Reconstructs a 12-byte fingerprint from two Int64String values. */
export const fingerprintIntsToFingerprint = (parts) => {
    let part1 = BigInt(parts[0]);
    let part2 = BigInt(parts[1]);
    const hash = new Uint8Array(12);
    for (let i = 5; i >= 0; i--) {
        hash[i] = Number(part1 & BigInt(0xff));
        part1 >>= BigInt(8);
    }
    for (let i = 11; i >= 6; i--) {
        hash[i] = Number(part2 & BigInt(0xff));
        part2 >>= BigInt(8);
    }
    return hash;
};
/** Select both the user and Evolu tables. */
export const selectTableAndColumnInfo = sql `
  select
    sqlite_master.name as tableName,
    table_info.name as columnName
  from
    sqlite_master
    join pragma_table_info(sqlite_master.name) as table_info;
`;
/** Select only the user indexes. */
export const selectUserIndexes = sql `
  select name, sql
  from sqlite_master
  where type = 'index' and name not like 'sqlite_%' and name not like 'evolu_%';
`;
/** Select both the user and Evolu indexes. */
export const selectAllIndexes = sql `
  select name, sql
  from sqlite_master
  where type = 'index' and name not like 'sqlite_%';
`;
export const createTable = (tableName, columns) => `
    create table "${sanitizeIdentifier(identifier(tableName))}" (
      "id" text primary key,
      ${columns
    .filter((c) => c !== "id")
    // "A column with affinity BLOB does not prefer one storage class over another
    // and no attempt is made to coerce data from one storage class into another."
    // https://www.sqlite.org/datatype3.html
    .map((name) => `"${sanitizeIdentifier(identifier(name))}" blob`)
    .join(", ")}
    );
  `;
export const addColumn = (tableName, newColumn) => sql `
  alter table ${identifier(tableName)} add column ${identifier(newColumn)} blob;
`.sql;
export const dropIndex = (name) => sql `
  drop index ${identifier(name)};
`.sql;
/**
 * The Message table has two versions: one for the Client and one for the Relay.
 * The only difference is that the Relay version has DbChange encrypted while
 * the Client version stores it decrypted in evolu_history table.
 *
 * TODO: Perf https://www.sqlite.org/withoutrowid.html test with real data.
 */
export const createMessageTable = (target) => target === "client"
    ? sql `
        create table evolu_message (
          t blob primary key,
          h1 integer,
          h2 integer,
          c integer,
          l integer not null
        )
        strict;
      `
    : sql `
        create table evolu_message (
          t blob primary key,
          h1 integer,
          h2 integer,
          c integer,
          l integer not null,
          d blob not null
        )
        strict;
      `;
// TODO: Covering index for Relay with d blob
export const createMessageTableIndex = sql `
  create index evolu_message_l_t_h1_h2_c on evolu_message (l, t, h1, h2, c);
`;
/**
 * The History table stores all values per timestamp, table, row, and column.
 * It's required for merging without conflicts. Evolu uses last-write-win CRDT.
 * In case of last-write-win value isn't what we want, we can use time travel.
 * The current implementation prefers performance over storage size. The History
 * table denormalizes Timestamp and DbChange to leverage a covering index.
 * Hence, every value change has its timestamp, table, row, and column. In the
 * future, we will rethink that and store history more efficiently.
 */
export const createHistoryTable = sql `
  create table evolu_history (
    timestamp blob not null,
    "table" text not null,
    "row" blob not null,
    "column" text not null,
    value any
  )
  strict;
`;
// `row` is first because it has the highest cardinality.
export const createHistoryTableIndex1 = sql `
  create unique index evolu_history_row_column_table_timestampDesc on evolu_history (
    "row",
    "column",
    "table",
    timestamp desc
  );
`;
/**
 * It's not a covering index because it would slow down write performance and
 * increase index size.
 */
export const createHistoryTableIndex2 = sql `
  create index evolu_history_table_timestamp on evolu_history (timestamp);
`;
export const createOwnerTable = sql `
  create table evolu_owner (
    id text not null,
    mnemonic text not null,
    encryptionKey blob not null,
    timestamp text not null,
    protocolVersion integer not null
  )
  strict;
`;
export const insertOwner = (id, mnemonic, encryptionKey, timestamp) => sql `
  insert into evolu_owner
    (id, mnemonic, encryptionKey, timestamp, protocolVersion)
  values
    (${id}, ${mnemonic}, ${encryptionKey}, ${timestamp}, ${protocolVersion});
`;
export const selectOwner = sql `
  select id, mnemonic, encryptionKey, timestamp, protocolVersion
  from evolu_owner
  limit 1;
`;
export const selectTimestamp = sql `
  select timestamp from evolu_owner limit 1;
`;
export const updateTimestamp = (timestamp) => prepare(sql `
    update evolu_owner
    set timestamp = ${timestamp};
  `);
/**
 * Programming in SQL is like a code golfing competition 🫠. The code is already
 * blazingly fast, but there is a chance it could be even faster if someone with
 * better knowledge of SQLite internals would take a look—for example, those
 * repeated queries. I didn't find a better way how to write them. I think
 * lateral join would help. Anyway, it's interesting how much logic can be
 * expressed with so little code.
 *
 * Notes:
 *
 * - RBSR SQL is idempotent (no roundtrips 🤟).
 * - Insert and update must be separated because it's impossible to insert and
 *   update within one statement in SQLite.
 * - Level 1 is simplified because there are no children that has to be read.
 */
export const insertLevel1 = `
  insert into evolu_message (l, t, h1, h2, c) values (1, $t, $h1, $h2, 1)
  on conflict do nothing
`;
/** SQLite doesn't support xor, but it can be emulated. */
const x = (a, b) => `(${a} | ${b}) - (${a} & ${b})`;
export const updateLevel1 = `
  with
    p(l, t, h1, h2) as (
      select (select max(l) + 1 from evolu_message), null, null, null
      union all
      select p.l - 1, ifnull((
        select t from evolu_message
        where l = p.l - 1 and t > $t and (p.t is null or t < p.t) order by t limit 1
      ), p.t), (
        select h1 from evolu_message
        where l = p.l - 1 and t > $t and (p.t is null or t < p.t) order by t limit 1
      ), (
        select h2 from evolu_message
        where l = p.l - 1 and t > $t and (p.t is null or t < p.t) order by t limit 1
      )
      from p where p.l > 2
    ),
    u(t, h1, h2) as (
      select t, ${x("$h1", "h1")}, ${x("$h2", "h2")} from p where h1 is not null
    )
    update evolu_message set h1 = u.h1, h2 = u.h2, c = c + 1
    from u where changes() > 0 and evolu_message.t = u.t
  `;
export const insertLevelX = `
  insert into evolu_message (t, l) values ($t, $l) on conflict do nothing
`;
export const updateLevelX = `
  with
    s(t) as (
      select ifnull((select max(t) from evolu_message where t < $t and l >= $l), 0)
    ),
    c(ut, l, t, h1, h2, c, mt) as (
      select $t, $l, (select t from s), $h1, $h2, 1, (select t from s)
      union all
      select null, c.l - 1, ifnull(m.t, c.t), m.h1, m.h2, m.c, ifnull((
        select max(t) from evolu_message where t > c.t and t < $t and l = c.l - 1
      ), mt)
      from c left join evolu_message as m
        on m.l = c.l - 1 and m.t > c.t and m.t < $t
      where c.t = c.mt and c.l > 1
    ),
    c2(rn, l, t, h1, h2, c) as (
      select row_number() over (order by l), l, ut, h1, h2, c from c
      where h1 is not null
    ),
    c3(rn, l, t, h1, h2, c) as (
      select rn, l, t, h1, h2, c from c2 where rn = 1
      union all
      select c3.rn + 1, c2.l, c2.t, ${x("c2.h1", "c3.h1")}, ${x("c2.h2", "c3.h2")}, c2.c + c3.c
      from c3, c2 where c2.rn = c3.rn + 1
    ),
    c4(l, t, h1, h2, c, rn) as (
      select l, t, h1, h2, c, max(rn) from c3 group by l
    ),
    n(l, t, h1, h2, c) as (
      select (select max(l) + 1 from evolu_message), null, null, null, null
      union all
      select n.l - 1, ifnull((
        select t from evolu_message
        where l = n.l - 1 and t > $t and (n.t is null or t < n.t) order by t limit 1
      ), n.t), (
        select h1 from evolu_message
        where l = n.l - 1 and t > $t and (n.t is null or t < n.t) order by t limit 1
      ), (
        select h2 from evolu_message
        where l = n.l - 1 and t > $t and (n.t is null or t < n.t) order by t limit 1
      ), (
        select c from evolu_message
        where l = n.l - 1 and t > $t and (n.t is null or t < n.t) order by t limit 1
      )
      from n where l - 1 > (select min(l) from c4)
    ),
    u(ut, uh1, uh2, uc) as (
      select t, h1, h2, c from c4 where t is not null
      union all
      select max(t), iif(l > $l, ${x("$h1", "h1")}, (
        select ${x("c4.h1", "n.h1")} from c4 where c4.l =
          (select max(l) from c4 where c4.l < n.l)
      )), iif(l > $l, ${x("$h2", "h2")}, (
        select ${x("c4.h2", "n.h2")} from c4 where c4.l =
          (select max(l) from c4 where c4.l < n.l)
      )), iif(l > $l, c + 1, (
        select n.c - c4.c from c4 where c4.l =
          (select max(l) from c4 where c4.l < n.l)
      ))
      from n where t is not null group by t
    )
  update evolu_message set h1 = uh1, h2 = uh2, c = uc
  from u where changes() > 0 and t = ut
`;
export const deleteRowFrom = (table, id) => sql `
  delete from ${identifier(table)} where id = ${id};
`;
export const insertOrIgnoreIntoEvoluHistory = (timestamp, message, id, column, value) => sql `
  insert or ignore into evolu_history
    (timestamp, "table", "row", "column", value)
  values
    (${timestamp}, ${message.change.table}, ${id}, ${column}, ${value});
`;
export const upsertOrIgnoreValueIntoTable = (id, column, table, value, date, timestamp) => prepare(sql `
    with
      lastTimestamp as (
        select timestamp
        from evolu_history
        where "row" = ${id} and "column" = ${column} and "table" = ${table}
        order by timestamp desc
        limit 1
      )
    insert into ${identifier(table)}
      ("id", ${identifier(column)}, createdAt, updatedAt)
    select ${id}, ${value}, ${date}, ${date}
    where
      (select timestamp from lastTimestamp) is null
      or (select timestamp from lastTimestamp) < ${timestamp}
    on conflict ("id") do update
      set
        ${identifier(column)} = ${value},
        updatedAt = ${date}
      where
        (select timestamp from lastTimestamp) is null
        or (select timestamp from lastTimestamp) < ${timestamp};
  `);
export const dropTable = (table) => sql `
  drop table ${identifier(table)};
`;
export const startReconciliation = `
  with
    ml(ml) as (select max(l) from evolu_message),
    sc(l, mt, c) as (
      select (select ml + 1 from ml), zeroblob(0), 0
      union all
      select sc.l - 1, ifnull((select max(t) from evolu_message as m
        where sc.l > 1 and m.l = sc.l - 1 and m.t > sc.mt
      ), sc.mt), ifnull((select sum(m.c) from evolu_message as m
        where sc.l > 1 and m.l = sc.l - 1 and m.t > sc.mt
      ), 0)
      from sc where sc.l > 1
    ),
    tc as (select sum(c) as tc from sc),
    ts(t, b, h1, h2) as (
      -- limit makes the whole select faster with 10k, it's
      -- almost as fast as select null, null, null, null
      select t, null, null, null from evolu_message limit ($buckets * 2) - 1
    ),
    rs(i, l, u, ipb, bwe) as (
      select 0, 0, 0, floor((select tc from tc) / $buckets), ((select tc from tc) % $buckets)
      union all select i + 1, u, u + (ipb + (iif(i < bwe, 1, 0))), ipb, bwe
      from rs where i < $buckets
    ),
    rs2(c) as (select u from rs where i > 0),
    rs3(c, b, nt, nc, nh1, nh2, ft, tt, dl, ic, h1, h2) as (
      select c, 1, null, null, null, null, zeroblob(0), X'FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF', ml, 0, 0, 0
      from rs2, ml
      union all
      select
        c,
        not b,
        iif(b, (select t from evolu_message where l = dl and t > ft and t < tt order by t limit 1), null),
        iif(b, (select c from evolu_message where l = dl and t > ft and t < tt order by t limit 1), null),
        iif(b, (select h1 from evolu_message where l = dl and t > ft and t < tt order by t limit 1), null),
        iif(b, (select h2 from evolu_message where l = dl and t > ft and t < tt order by t limit 1), null),
        iif(b, ft, iif(ic + nc <= c, nt, ft)),
        iif(b, tt, iif(ic + nc <= c, tt, ifnull(nt, tt))),
        iif(b, dl, iif(ic + nc <= c, dl, dl - 1)),
        iif(b, ic, iif(ic + nc <= c, ic + nc, ic)),
        iif(b, h1, iif(ic + nc <= c, ${x("h1", "nh1")}, h1)),
        iif(b, h2, iif(ic + nc <= c, ${x("h2", "nh2")}, h2))
      from rs3
      where iif(b, 1, ic != c)
    ),
    rs4(h1, h2, t, rn) as (
      select h1, h2, (
        select min(t) from evolu_message where t > ft
      ), row_number() over (order by c) from rs3 where c = ic and b = 1
    ),
    rs5(oh1, oh2, b, rn, h1, h2) as (
      select h1, h2, t, rn, h1, h2 from rs4 where rn = 1
      union all
      select rs4.h1, rs4.h2, t, rs4.rn, ${x("rs5.oh1", "rs4.h1")}, ${x("rs5.oh2", "rs4.h2")}
      from rs4, rs5 on rs4.rn = rs5.rn + 1
    ),
    rs6(t, b, h1, h2) as (
      select null, b, cast(h1 as text) as h1, cast(h2 as text) as h2 from rs5
    )
  select * from ts where (select tc from tc) < $buckets * 2
  union all
  select * from rs6 where (select tc from tc) >= $buckets * 2
`;
