import * as bip39 from "@scure/bip39";
import { wordlist } from "@scure/bip39/wordlists/english";
import { isNonEmptyArray, isNonEmptyReadonlyArray, } from "../Array.js";
import { errorToTransferableError } from "../Error.js";
import { constVoid } from "../Function.js";
import { objectToEntries } from "../Object.js";
import { ok } from "../Result.js";
import { DateIso, object, String, } from "../Type.js";
import { binaryTimestampToFingerprint, createInitialTimestamp, deriveOwnerIdAndEncryptionKey, } from "./Crypto.js";
import { makePatches } from "./Diff.js";
import { idToBinaryId, protocolVersion, } from "./Protocol.js";
import { createQueryRowsCache, deserializeQuery, } from "./Query.js";
import { addColumn, createHistoryTable, createHistoryTableIndex1, createHistoryTableIndex2, createMessageTable, createMessageTableIndex, createOwnerTable, createTable, deleteRowFrom, dropIndex, dropTable, fingerprintToFingerprintInts, insertLevel1, insertLevelX, insertOrIgnoreIntoEvoluHistory, insertOwner, selectAllIndexes, selectOwner, selectTableAndColumnInfo, selectTimestamp, selectUserIndexes, updateLevel1, updateLevelX, updateTimestamp, upsertOrIgnoreValueIntoTable, } from "./Sql.js";
import { addCommonSqliteFeatures, explainQueryPlan, prepare, sql, } from "./Sqlite.js";
import { createTimestamp, encodeTimestamp, Millis, sendTimestamp, timestampStringToTimestamp, timestampToTimestampString, } from "./Timestamp.js";
export const Index = object({
    name: String,
    sql: String,
});
// TODO: Use Eq
const indexesAreEqual = (self, that) => self.name === that.name && self.sql === that.sql;
export const createDbWorker = (deps) => {
    // A placeholder for DbWorker onMessage callback.
    let onMessage = constVoid;
    const { promise: initDeps, resolve: resolveInitDeps } = Promise.withResolvers();
    const handlers = {
        init: async (message) => {
            const { createSqlite, createLogger, ...rest } = deps;
            const logger = createLogger(message.config);
            const sqlite = addCommonSqliteFeatures({
                ...logger,
                ...createSqlite(message.config),
            });
            const initDeps = {
                ...sqlite,
                ...logger,
                ...rest,
                ...message.config,
                ...createQueryRowsCache(),
                // TODO: createSyncWorker
            };
            await sqlite.transaction("exclusive")(async () => {
                const currentDbSchema = await getDbSchema(sqlite)();
                await ensureDbSchema(sqlite)(message.dbSchema, currentDbSchema);
                await maybeMigrateToVersion1(initDeps)(currentDbSchema);
                const ownerExists = currentDbSchema.tables.some((table) => table.name === "evolu_owner");
                const owner = ownerExists
                    ? await getOwner(sqlite)
                    : await createOwner(initDeps)(message.config.mnemonic);
                if (!ownerExists && isNonEmptyReadonlyArray(message.initialData)) {
                    await applyChanges(initDeps)(message.initialData);
                }
                onMessage({ type: "onInit", owner });
                resolveInitDeps(initDeps);
            });
        },
        mutate: async (message) => {
            const deps = await initDeps;
            await deps.transaction("exclusive")(async () => {
                const toSyncChanges = [];
                const localOnlyChanges = [];
                for (const change of message.changes) {
                    // Table name starting with '_' is local-only (not synced).
                    if (change.table.startsWith("_"))
                        localOnlyChanges.push(change);
                    else
                        toSyncChanges.push(change);
                }
                for (const change of localOnlyChanges) {
                    if (change.values["isDeleted"] === 1) {
                        await deps.exec(deleteRowFrom(change.table, change.id));
                    }
                    else {
                        const millis = Millis.from(deps.now());
                        if (!millis.ok) {
                            onMessage({
                                type: "onError",
                                error: { type: "TimestampTimeOutOfRangeError" },
                            });
                            return;
                        }
                        const message = {
                            timestamp: createTimestamp({ millis: millis.value }),
                            change,
                        };
                        await applyMessage(deps)(message);
                    }
                }
                /**
                 * We don't have to wait for the transaction to end because changes are
                 * idempotent, so there is no reason why they should fail. We want to
                 * call onChange ASAP.
                 */
                const onChange = async () => {
                    deps.log("[db]", "onChange");
                    onMessage({
                        type: "onChange",
                        patches: await loadQueries(deps)(message.subscribedQueries),
                        onCompleteIds: message.onCompleteIds,
                    });
                };
                if (isNonEmptyArray(toSyncChanges)) {
                    await applyChanges(deps)(toSyncChanges, onChange);
                }
                else {
                    await onChange();
                }
            });
        },
        query: async (message) => {
            const deps = await initDeps;
            await deps.transaction("shared")(async () => {
                onMessage({
                    type: "onChange",
                    patches: await loadQueries(deps)(message.queries),
                    onCompleteIds: [],
                });
            });
        },
        reset: async (message) => {
            const deps = await initDeps;
            await deps.transaction("last")(async () => {
                await dropAllTables(deps);
                if (message.restore) {
                    const currentDbSchema = await getDbSchema(deps)();
                    await ensureDbSchema(deps)(message.restore.dbSchema, currentDbSchema);
                    await createOwner(deps)(message.restore.mnemonic);
                }
                onMessage({
                    type: "onReset",
                    onCompleteId: message.onCompleteId,
                    reload: message.reload,
                });
            });
        },
        ensureSchema: async (message) => {
            const deps = await initDeps;
            await deps.transaction("exclusive")(async () => {
                const currentSchema = await getDbSchema(deps)();
                await ensureDbSchema(deps)(message.dbSchema, currentSchema);
            });
        },
        export: async (message) => {
            const deps = await initDeps;
            await deps.transaction("exclusive")(async () => {
                const file = await deps.export();
                onMessage({
                    type: "onExport",
                    onCompleteId: message.onCompleteId,
                    file,
                });
            });
        },
    };
    const dbWorker = {
        postMessage: (message) => {
            handlers[message.type](message).catch((error) => {
                onMessage({
                    type: "onError",
                    error: errorToTransferableError(error),
                });
            });
        },
        onMessage: (callback) => {
            onMessage = callback;
        },
    };
    return dbWorker;
};
export const getDbSchema = ({ exec }) => async (allIndexes) => {
    const map = new Map();
    const { rows: tableAndColumnInfoRows } = await exec(selectTableAndColumnInfo);
    tableAndColumnInfoRows.forEach((row) => {
        const { tableName, columnName } = row;
        if (!map.has(tableName))
            map.set(tableName, []);
        map.get(tableName)?.push(columnName);
    });
    const tables = Array.from(map, ([name, columns]) => ({ name, columns }));
    const { rows: indexesRows } = await exec(allIndexes ? selectAllIndexes : selectUserIndexes);
    const indexes = indexesRows.map((row) => ({
        name: row.name,
        /**
         * SQLite returns "CREATE INDEX" for "create index" for some reason.
         * Other keywords remain unchanged. We have to normalize the casing for
         * {@link indexesAreEqual} manually.
         */
        sql: row.sql
            .replace("CREATE INDEX", "create index")
            .replace("CREATE UNIQUE INDEX", "create unique index"),
    }));
    return { tables, indexes };
};
const ensureDbSchema = ({ exec }) => async (newSchema, currentSchema, options) => {
    const sqls = [];
    newSchema.tables.forEach((newTable) => {
        const currentTable = currentSchema.tables.find((t) => t.name === newTable.name);
        if (!currentTable) {
            sqls.push(createTable(newTable.name, newTable.columns));
        }
        else {
            newTable.columns
                .filter((newColumn) => !currentTable.columns.includes(newColumn))
                .forEach((newColumn) => {
                sqls.push(addColumn(newTable.name, newColumn));
            });
        }
    });
    if (options?.ignoreIndexes !== true) {
        // Remove current indexes that are not in the newSchema.
        currentSchema.indexes
            .filter((currentIndex) => !newSchema.indexes.some((newIndex) => indexesAreEqual(newIndex, currentIndex)))
            .forEach((index) => {
            sqls.push(dropIndex(index.name));
        });
        // Add new indexes that are not in the currentSchema.
        newSchema.indexes
            .filter((newIndex) => !currentSchema.indexes.some((currentIndex) => indexesAreEqual(newIndex, currentIndex)))
            .forEach((newIndex) => {
            sqls.push(`${newIndex.sql};`);
        });
    }
    for (const sql of sqls) {
        await exec({ sql });
    }
};
const getOwner = async ({ exec }) => {
    const { rows } = await exec(selectOwner);
    const row = rows[0];
    return {
        id: row.id,
        mnemonic: row.mnemonic,
        encryptionKey: row.encryptionKey,
        protocolVersion: row.protocolVersion,
        nodeId: timestampStringToTimestamp(row.timestamp).nodeId,
    };
};
const createMnemonic = () => bip39.generateMnemonic(wordlist, 128);
const createOwner = (deps) => async (mnemonic = createMnemonic()) => {
    const { ownerId, encryptionKey } = deriveOwnerIdAndEncryptionKey(deps)(mnemonic);
    const initialTimestamp = createInitialTimestamp(deps);
    const owner = {
        mnemonic,
        id: ownerId,
        encryptionKey,
        nodeId: initialTimestamp.nodeId,
        protocolVersion,
    };
    for (const query of [
        createMessageTable("client"),
        createMessageTableIndex,
        createHistoryTable,
        createHistoryTableIndex1,
        createHistoryTableIndex2,
        createOwnerTable,
        insertOwner(owner.id, owner.mnemonic, owner.encryptionKey, timestampToTimestampString(initialTimestamp)),
    ]) {
        await deps.exec(query);
    }
    return owner;
};
const applyChanges = (deps) => async (changes, onChange) => {
    let timestamp = await deps
        // Can't be prepared because it has no args.
        .exec(selectTimestamp)
        .then(({ rows: [row] }) => timestampStringToTimestamp(row.timestamp));
    const messages = [];
    for (const change of changes) {
        const nextTimestamp = sendTimestamp(deps)(timestamp);
        if (!nextTimestamp.ok)
            return nextTimestamp;
        timestamp = nextTimestamp.value;
        messages.push({ timestamp, change });
    }
    await applyMessages(deps)(messages);
    if (onChange)
        await onChange();
    await deps.exec(updateTimestamp(timestampToTimestampString(timestamp)));
    return ok(messages);
};
const applyMessages = (deps) => async (messages) => {
    for (const message of messages) {
        await applyMessage(deps)(message);
        await updateEvoluTables(deps)(message);
    }
};
/**
 * Apply the message if no timestamp exists or the most recent timestamp for a
 * specific row, table, and column is older. This timestamp check is executed
 * within the database, ensuring high efficiency with no additional roundtrips.
 */
const applyMessage = (sqlite) => async (message) => {
    const date = DateIso.fromParent(new Date(message.timestamp.millis)).value;
    const timestamp = encodeTimestamp(message.timestamp);
    for (const [column, value] of objectToEntries(message.change.values)) {
        await sqlite.exec(upsertOrIgnoreValueIntoTable(message.change.id, column, message.change.table, value, date, timestamp));
    }
};
export const updateEvoluTables = (deps) => async (message) => {
    const level = randomSkiplistLevel(deps);
    const queries = [];
    const timestamp = encodeTimestamp(message.timestamp);
    const [part1, part2] = fingerprintToFingerprintInts(binaryTimestampToFingerprint(timestamp));
    const id = idToBinaryId(message.change.id);
    if (level === 1) {
        queries.push({
            sql: insertLevel1,
            parameters: { $t: timestamp, $h1: part1, $h2: part2 },
        }, {
            sql: updateLevel1,
            parameters: { $t: timestamp, $h1: part1, $h2: part2 },
        });
    }
    else {
        queries.push({ sql: insertLevelX, parameters: { $t: timestamp, $l: level } }, {
            sql: updateLevelX,
            parameters: { $t: timestamp, $l: level, $h1: part1, $h2: part2 },
        });
    }
    Object.entries(message.change.values).forEach(([column, value]) => {
        queries.push(insertOrIgnoreIntoEvoluHistory(timestamp, message, id, column, value));
    });
    for (const query of queries) {
        await deps.exec(prepare(query));
    }
};
/**
 * 0.25 is faster than 0.5 (Redis uses the same). The lower the capacity, the
 * more hashes are computed.
 */
const skiplistProbability = 0.25;
const skiplistMaxLevel = 32;
export const randomSkiplistLevel = (random) => {
    let level = 1;
    while (random.next() <= skiplistProbability && level < skiplistMaxLevel) {
        level += 1;
    }
    return level;
};
const loadQueries = (deps) => async (queries) => {
    const queriesRows = [];
    for (const query of queries) {
        const sqlQuery = deserializeQuery(query);
        const { rows } = await deps.exec(sqlQuery);
        queriesRows.push([query, rows]);
        if (sqlQuery.options?.logExplainQueryPlan) {
            await explainQueryPlan(deps)(sqlQuery);
        }
    }
    const previousState = deps.get();
    deps.set(queriesRows);
    const currentState = deps.get();
    return queries.map((query) => ({
        query,
        patches: makePatches(previousState.get(query), currentState.get(query) ?? []),
    }));
};
export const maybeMigrateToVersion1 = ({ exec, ...rest }) => async (schema) => {
    // evolu_history is a new table because Evolu stores more values per timestamp
    const hasOwnerButNoHistory = schema.tables.some((t) => t.name === "evolu_owner") &&
        !schema.tables.some((t) => t.name === "evolu_history");
    if (!hasOwnerButNoHistory)
        return;
    for (const query of [
        sql `alter table evolu_owner drop column merkleTree;`,
        sql `alter table evolu_owner add column protocolVersion blob;`,
        sql `update evolu_owner set protocolVersion = 1;`,
    ]) {
        await exec(query);
    }
    const { rows } = (await exec(sql `
      select timestamp, "table", "row", "column", value from evolu_message;
    `));
    // We can drop and recreate without triggers, views, and foreign key constraints.
    // https://www.sqlite.org/lang_altertable.html
    for (const query of [
        sql `drop table evolu_message;`,
        createMessageTable("client"),
        createHistoryTable,
    ]) {
        await exec(query);
    }
    for (const row of rows) {
        const value = row.value;
        await updateEvoluTables({ exec, ...rest })({
            timestamp: timestampStringToTimestamp(row.timestamp),
            change: {
                id: row.row,
                table: row.table,
                values: { [row.column]: value },
            },
        });
    }
    // Inserting is faster without indexes, so we add them after.
    for (const query of [
        createMessageTableIndex,
        createHistoryTableIndex1,
        createHistoryTableIndex2,
    ]) {
        await exec(query);
    }
};
const dropAllTables = async (sqlite) => {
    const schema = await getDbSchema(sqlite)();
    for (const table of schema.tables) {
        /**
         * The dropped table is completely removed from the database schema and the
         * disk file. The table can not be recovered. All indices and triggers
         * associated with the table are also deleted.
         * https://sqlite.org/lang_droptable.html
         */
        await sqlite.exec(dropTable(table.name));
    }
};
