import { ok } from "../Result.js";
import { Base64Url, Boolean, brand, Id, length, maxLength, minLength, Mnemonic, Null, Number, object, regex, String, transform, Uint8Array, union, } from "../Type.js";
/**
 * Creates an {@link Id}.
 *
 * ### Example
 *
 * ```ts
 * // string & Brand<"Id">
 * const id = createId(deps);
 *
 * // string & Brand<"Id"> & Brand<"Todo">
 * const id = createId<TodoId>(deps);
 * ```
 */
export const createId = (deps) => deps.nanoid();
export const Base64Url256 = maxLength(256)(Base64Url);
/**
 * SQLite represents boolean values using `0` (false) and `1` (true) instead of
 * a dedicated boolean type. This transform Type ensures that values conform to
 * SQLite's boolean representation.
 *
 * See: https://www.sqlite.org/quirks.html#no_separate_boolean_datatype
 */
export const SqliteBoolean = transform(Boolean, union(0, 1), (value) => ok(value ? 1 : 0), (value) => value === 1);
/**
 * `DbIdentifier` is used for database (tables and columns) names. It enforces
 * that the string length is at least 1 character and does not exceed 42.
 */
export const DbIdentifier = minLength(1)(maxLength(64)(Base64Url));
export const TableName = brand("TableName", DbIdentifier);
export const ColumnName = brand("ColumnName", DbIdentifier);
/**
 * DbValue is a value that can be stored in an Evolu-compatible SQL database. It
 * is modeled after what SQLite allows.
 *
 * Note that Evolu can't support Int64 because expo-sqlite (and others) do not
 * support it yet.
 */
export const DbValue = union(Null, String, Number, Uint8Array);
/** The unique identifier of {@link EvoluOwner} derived from its {@link Mnemonic}. */
export const OwnerId = brand("OwnerId", Id);
/** The encryption key safely derived from {@link Mnemonic}. */
export const EncryptionKey = brand("EncryptionKey", length(32)(Uint8Array));
/**
 * A NodeID uniquely identifies an Owner's device. The 64-bit length (in binary
 * form) provides sufficient uniqueness because NodeID is created once per
 * device.
 *
 * https://lemire.me/blog/2019/12/12/are-64-bit-random-identifiers-free-from-collision
 *
 * What will happen if two different devices of the same user will generate the
 * same NodeId? It's highly unlikely, but what if?
 *
 * Syncing between devices would stop because, from the point of view of the
 * Relay, those two devices would be one device, and there is no reason to send
 * timestamps the device already has. The fix would be resetting the device,
 * which would generate a new NodeId. There would be no data loss because
 * sending to a Relay would still work; it only would not return data.
 *
 * Timestamp duplication isn't possible because the timestamp is a unique key in
 * an SQL table. If two different devices with the same NodeId create a
 * timestamp within the exact millisecond, the Relay ignores the latter. That's
 * the only case when a user could lose data because the affected timestamp
 * would not be stored in the Relay, and reset would delete it. Remember, that's
 * even rarer than a NodeId collision because it can only happen within the same
 * ms.
 */
export const NodeId = regex("NodeId", /^[a-f0-9]{16}$/)(String);
/**
 * The Owner is an Evolu user. Instead of the traditional email and password,
 * the Owner uses a mnemonic (also called a "seed phrase"). This mnemonic
 * consists of 12 words in a specific order, chosen from a predefined list.
 *
 * The BIP39 mnemonic is a human-readable method for securely storing a private
 * key. The mnemonic is generated locally on the user's device and should never
 * be shared with anyone.
 */
export const EvoluOwner = object({
    mnemonic: Mnemonic,
    id: OwnerId,
    encryptionKey: EncryptionKey,
    protocolVersion: Number, // TODO: PositiveInt
    nodeId: NodeId,
});
